    # Deterministic ordering: farthest, then demand, then id
    arr = []
    for c in customers:
        arr.append((d(depot, c), demand_of(c), c))
    arr.sort(key=lambda x: (-x[0], -x[1], x[2]))
    unrouted = [x[2] for x in arr]

    routes = []
    loads = []

    # Phase 1: sweep-style greedy route construction
    while unrouted:
        seed_index = -1
        seed = None
        for i in range(len(unrouted)):
            c = unrouted[i]
            if demand_of(c) <= capacity:
                seed_index = i
                seed = c
                break
        if seed is None:
            seed_index = 0
            seed = unrouted[0]
        route = [seed]
        load = demand_of(seed)
        unrouted.pop(seed_index)

        while True:
            last = route[-1]
            best_i = -1
            best_c = None
            best_key = None
            for i in range(len(unrouted)):
                c = unrouted[i]
                dc = demand_of(c)
                if load + dc > capacity:
                    continue
                inc = d(last, c) + d(c, depot) - d(last, depot)
                key = (inc, -dc, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best_i = i
                    best_c = c
            if best_c is None:
                break
            route.append(best_c)
            load += demand_of(best_c)
            unrouted.pop(best_i)

        routes.append(route)
        loads.append(load)

    # Phase 2: repair leftover customers by insertion or new routes
    if unrouted:
        leftovers = unrouted
        unrouted = []
        for c in leftovers:
            dc = demand_of(c)
            best_r = -1
            best_p = -1
            best_key = None
            for r in range(len(routes)):
                if loads[r] + dc > capacity:
                    continue
                route = routes[r]
                prev = depot
                for p in range(len(route) + 1):
                    nxt = depot if p == len(route) else route[p]
                    cost = d(prev, c) + d(c, nxt) - d(prev, nxt)
                    key = (cost, r, p)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_r = r
                        best_p = p
                    if p < len(route):
                        prev = route[p]
            if best_r == -1:
                routes.append([c])
                loads.append(dc)
            else:
                routes[best_r].insert(best_p, c)
                loads[best_r] += dc

    def route_cost(route):
        if not route:
            return 0
        total = d(depot, route[0])
        for i in range(len(route) - 1):
            total += d(route[i], route[i + 1])
        total += d(route[-1], depot)
        return total

    # Phase 3: simple local search within routes (2-opt and relocate to improve order)
    for _ in range(2):
        improved_any = False
        for r in range(len(routes)):
            route = routes[r]
            n = len(route)
            if n >= 4:
                improved = True
                while improved:
                    improved = False
                    best_delta = 0
                    best_i = -1
                    best_j = -1
                    for i in range(n - 2):
                        a = depot if i == 0 else route[i - 1]
                        b = route[i]
                        for j in range(i + 1, n):
                            c = route[j]
                            d2 = depot if j == n - 1 else route[j + 1]
                            delta = (d(a, c) + d(b, d2)) - (d(a, b) + d(c, d2))
                            if delta < best_delta - 1e-12:
                                best_delta = delta
                                best_i = i
                                best_j = j
                    if best_i != -1:
                        route[best_i:best_j + 1] = route[best_i:best_j + 1][::-1]
                        improved = True
                        improved_any = True
                        n = len(route)
            # greedy relocate within route
            n = len(route)
            if n >= 3:
                changed = True
                while changed:
                    changed = False
                    current = route_cost(route)
                    best_move = None
                    best_val = current
                    for i in range(n):
                        c = route[i]
                        rem = route[:i] + route[i + 1:]
                        m = len(rem)
                        for p in range(m + 1):
                            newr = rem[:p] + [c] + rem[p:]
                            val = route_cost(newr)
                            if val < best_val - 1e-12:
                                best_val = val
                                best_move = (i, p, newr)
                    if best_move is not None:
                        route[:] = best_move[2]
                        changed = True
                        improved_any = True
        if not improved_any:
            break

    # Final cleanup: remove empty routes
    final_routes = []
    for r in routes:
        if r:
            final_routes.append(r)

    return final_routes
